-- ============================================================================
-- 06_produccion_susi_y_limpieza.sql
-- 1. Limpieza de columnas basura de TOTVS y depositos falsos en Hilados/Insumos
-- 2. Carga de estructuras faltantes (estructuras viejas) y mapeo 100% Codigo Susi
-- 3. Tablas de Planificacion de Produccion Diaria y Stock/Pedidos de Articulos
-- ============================================================================
BEGIN;

-- 1. Eliminar columnas obsoletas de TOTVS en articulos
ALTER TABLE articulos
  DROP COLUMN IF EXISTS almacen,
  DROP COLUMN IF EXISTS grupo,
  DROP COLUMN IF EXISTS "segundaUnidadMedida",
  DROP COLUMN IF EXISTS "factorConversion",
  DROP COLUMN IF EXISTS "tipoConversion",
  DROP COLUMN IF EXISTS "usaLote",
  DROP COLUMN IF EXISTS "usaUbicacion",
  DROP COLUMN IF EXISTS "ctdEmbalaje",
  DROP COLUMN IF EXISTS "puntoPedido",
  DROP COLUMN IF EXISTS "stockSeguridad",
  DROP COLUMN IF EXISTS "plazoEntrega",
  DROP COLUMN IF EXISTS "tipoPlazo",
  DROP COLUMN IF EXISTS "loteEconomico",
  DROP COLUMN IF EXISTS "tipoDecOP",
  DROP COLUMN IF EXISTS "entraMrp",
  DROP COLUMN IF EXISTS "stockMaximo",
  DROP COLUMN IF EXISTS "atiendeNe",
  DROP COLUMN IF EXISTS "tipoCC",
  DROP COLUMN IF EXISTS "detalleFalla";

-- 2. Eliminar columnas obsoletas de TOTVS en articulo_estructuras
ALTER TABLE articulo_estructuras
  DROP COLUMN IF EXISTS posicion,
  DROP COLUMN IF EXISTS secuencia,
  DROP COLUMN IF EXISTS "fechaInicio",
  DROP COLUMN IF EXISTS "fechaFin",
  DROP COLUMN IF EXISTS "tipoFijoVariable",
  DROP COLUMN IF EXISTS "revisionInicial",
  DROP COLUMN IF EXISTS "revisionFinal",
  DROP COLUMN IF EXISTS "detalleFalla",
  DROP COLUMN IF EXISTS "componenteAnterior";

-- 3. Limpiar los 3 depositos falsos de articulos que se habian inyectado en depots de Hilado/Insumos
DELETE FROM positions WHERE "depositoId" IN ('11111111-1111-1111-1111-111111111111', '22222222-2222-2222-2222-222222222222', '33333333-3333-3333-3333-333333333333')
  AND id NOT IN (SELECT DISTINCT "posicionId" FROM stock_balance WHERE "posicionId" IS NOT NULL);
DELETE FROM depots WHERE id IN ('11111111-1111-1111-1111-111111111111', '22222222-2222-2222-2222-222222222222', '33333333-3333-3333-3333-333333333333')
  AND id NOT IN (SELECT DISTINCT "depositoId" FROM stock_balance WHERE "depositoId" IS NOT NULL);

-- 4. Insertar articulos de TEJIDO/COSTURA faltantes desde estructuras viejas
INSERT INTO articulos (codigo, descripcion, tipo, "unidadMedida", etapa, modelo, talle, variante, estado, origen, activo, "estadoRevision", "createdAt", "updatedAt") VALUES ('1376470-001_L_N_C', 'MEDIA COSTURA 1376470-001_L_N_C', 'PI', 'DOC', 'COSTURA', '1376470-001', 'L', 'N', 'CHEQUEADO', 'LIBRO1_V2', true, 'VERDE', now(), now()) ON CONFLICT (codigo) DO UPDATE SET etapa = EXCLUDED.etapa, modelo = COALESCE(articulos.modelo, EXCLUDED.modelo), talle = COALESCE(articulos.talle, EXCLUDED.talle), variante = COALESCE(articulos.variante, EXCLUDED.variante);
