-- 6. Asignar tiempo de ciclo estimado (95s por media) a los TEJIDO que aun no tengan tiempo en articulo_machine_types
INSERT INTO articulo_machine_types ("articuloId", "machineTypeId", "cycleTimeSeconds", "timeSource", status, preferida, "createdAt")
SELECT a.id, dm.id, 95, 'ESTIMADO_FAMILIA', 'ESTIMADO', true, now()
FROM articulos a
CROSS JOIN (
  SELECT id FROM machine_types WHERE category = 'TEJEDURIA' ORDER BY name LIMIT 1
) dm
WHERE a.etapa = 'TEJIDO'
  AND NOT EXISTS (SELECT 1 FROM articulo_machine_types amt WHERE amt."articuloId" = a.id)
ON CONFLICT ("articuloId", "machineTypeId") DO NOTHING;

